     1	//! Sending webhook calls.
     2	//!
     3	//! The notifier POSTs through a [`WebhookTransport`], so it runs against a
     4	//! real HTTP client in production and against [`HermeticTransport`] in tests
     5	//! and local runs.
     6	
     7	use std::collections::HashMap;
     8	use std::future::Future;
     9	use std::pin::Pin;
    10	use std::sync::Mutex;
    11	use std::time::Duration;
    12	
    13	use thiserror::Error;
    14	use url::Url;
    15	
    16	use crate::notifier::CANARY_URL;
    17	
    18	#[derive(Debug, Clone, Error, PartialEq, Eq)]
    19	pub enum WebhookError {
    20	    #[error("invalid webhook URL {0}")]
    21	    InvalidUrl(String),
    22	    #[error("{0} is unreachable")]
    23	    Unreachable(String),
    24	}
    25	
    26	/// The response to one POST: an HTTP status code, or why there was none.
    27	pub type PostFuture<'a> = Pin<Box<dyn Future<Output = Result<u16, WebhookError>> + Send + 'a>>;
    28	
    29	/// Something that can POST a JSON body to a webhook URL.
    30	pub trait WebhookTransport: Send + Sync {
    31	    fn post<'a>(&'a self, url: &'a str, body: &'a [u8]) -> PostFuture<'a>;
    32	}
    33	
    34	/// How an in-process endpoint answers.
    35	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
    36	pub enum Endpoint {
    37	    /// Answers `status` after `after`.
    38	    Respond { status: u16, after: Duration },
    39	    /// Accepts the connection and never answers.
    40	    Hang,
    41	}
    42	
    43	impl Endpoint {
    44	    /// Round trip of a healthy relying-party endpoint.
    45	    pub const TYPICAL_LATENCY: Duration = Duration::from_millis(150);
    46	
    47	    pub fn ok() -> Self {
    48	        Endpoint::Respond { status: 200, after: Self::TYPICAL_LATENCY }
    49	    }
    50	
    51	    pub fn status(status: u16) -> Self {
    52	        Endpoint::Respond { status, after: Self::TYPICAL_LATENCY }
    53	    }
    54	
    55	    pub fn slow(after: Duration) -> Self {
    56	        Endpoint::Respond { status: 200, after }
    57	    }
    58	}
    59	
    60	/// Answers every call in-process; nothing leaves the machine. Endpoints are
    61	/// registered per URL (or per host); anything unregistered is unreachable.
    62	/// The canary's host is answered by a local stub that acknowledges every
    63	/// call.
    64	#[derive(Debug)]
    65	pub struct HermeticTransport {
    66	    routes: Mutex<HashMap<String, Endpoint>>,
    67	    hosts: Mutex<HashMap<String, Endpoint>>,
    68	    received: Mutex<HashMap<String, Vec<Vec<u8>>>>,
    69	}
    70	
    71	impl Default for HermeticTransport {
    72	    fn default() -> Self {
    73	        HermeticTransport::new()
    74	    }
    75	}
    76	
    77	impl HermeticTransport {
    78	    pub fn new() -> Self {
    79	        let transport = HermeticTransport {
    80	            routes: Mutex::new(HashMap::new()),
    81	            hosts: Mutex::new(HashMap::new()),
    82	            received: Mutex::new(HashMap::new()),
    83	        };
    84	        let canary_host = Url::parse(CANARY_URL).ok().and_then(|u| u.host_str().map(str::to_string));
    85	        if let Some(host) = canary_host {
    86	            transport.route_host(&host, Endpoint::Respond { status: 200, after: Duration::ZERO });
    87	        }
    88	        transport
    89	    }
    90	
    91	    /// Answers calls to exactly `url` as `endpoint`.
    92	    pub fn route(&self, url: &str, endpoint: Endpoint) {
    93	        self.routes.lock().unwrap().insert(url.to_string(), endpoint);
    94	    }
    95	
    96	    /// Answers calls to any URL on `host` as `endpoint`.
    97	    pub fn route_host(&self, host: &str, endpoint: Endpoint) {
    98	        self.hosts.lock().unwrap().insert(host.to_string(), endpoint);
    99	    }
   100	
   101	    /// The bodies `url` has answered, in the order they arrived.
   102	    pub fn received(&self, url: &str) -> Vec<Vec<u8>> {
   103	        self.received.lock().unwrap().get(url).cloned().unwrap_or_default()
   104	    }
   105	
   106	    fn endpoint_for(&self, url: &str) -> Result<Endpoint, WebhookError> {
   107	        if let Some(endpoint) = self.routes.lock().unwrap().get(url) {
   108	            return Ok(*endpoint);
   109	        }
   110	        let parsed = Url::parse(url).map_err(|_| WebhookError::InvalidUrl(url.to_string()))?;
   111	        let host = parsed.host_str().ok_or_else(|| WebhookError::InvalidUrl(url.to_string()))?;
   112	        self.hosts.lock().unwrap().get(host).copied().ok_or_else(|| WebhookError::Unreachable(url.to_string()))
   113	    }
   114	}
   115	
   116	impl WebhookTransport for HermeticTransport {
   117	    fn post<'a>(&'a self, url: &'a str, body: &'a [u8]) -> PostFuture<'a> {
   118	        Box::pin(async move {
   119	            match self.endpoint_for(url)? {
   120	                Endpoint::Hang => std::future::pending().await,
   121	                Endpoint::Respond { status, after } => {
   122	                    tokio::time::sleep(after).await;
   123	                    self.received.lock().unwrap().entry(url.to_string()).or_default().push(body.to_vec());
   124	                    Ok(status)
   125	                }
   126	            }
   127	        })
   128	    }
   129	}

