128	    78	/// The HTTPS URL a `did:web` document is published at: `did.json` under the
129	    79	/// host's `/.well-known/` directory, with any further segments of the
130	    80	/// identifier as subdirectories. A port is written percent-encoded in the host
131	    81	/// segment (`example.com%3A8443`).
132	    82	pub fn did_web_url(did: &str) -> Result<String, ResolveError> {
133	    83	    let invalid = || ResolveError::InvalidDid(did.to_string());
134	    84	    let id = did.strip_prefix("did:web:").ok_or_else(invalid)?;
135	    85	    let mut segments = id.split(':');
136	    86	    let host = percent_decode(segments.next().unwrap_or_default()).ok_or_else(invalid)?;
137	    87	    if host.is_empty() || host.contains('/') {
138	    88	        return Err(invalid());
139	    89	    }
140	    90	    let path: Vec<String> = segments.map(percent_decode).collect::<Option<_>>().ok_or_else(invalid)?;
141	    91	    if path.iter().any(|s| s.is_empty() || s.contains('/')) {
142	    92	        return Err(invalid());
143	    93	    }
144	    94	    let mut url = format!("https://{host}/.well-known");
145	    95	    for segment in &path {
146	    96	        url.push('/');
