153	   103	fn percent_decode(segment: &str) -> Option<String> {
154	   104	    let bytes = segment.as_bytes();
155	   105	    let mut out = Vec::with_capacity(bytes.len());
156	   106	    let mut i = 0;
157	   107	    while i < bytes.len() {
158	   108	        if bytes[i] == b'%' {
159	   109	            let hex = std::str::from_utf8(bytes.get(i + 1..i + 3)?).ok()?;
160	   110	            out.push(u8::from_str_radix(hex, 16).ok()?);
161	   111	            i += 3;
162	   112	        } else {
163	   113	            out.push(bytes[i]);
164	   114	            i += 1;
165	   115	        }
166	   116	    }
167	   117	    String::from_utf8(out).ok()
168	   118	}
