198	   148	fn single_key_document(did: &str, multibase: &str) -> Result<Document, ResolveError> {
199	   149	    ed25519_multikey(did, multibase)?;
200	   150	    let vm_id = format!("{did}#{multibase}");
201	   151	    to_document(did, json!({
202	   152	        "@context": ["https://www.w3.org/ns/did/v1", "https://w3id.org/security/multikey/v1"],
203	   153	        "id": did,
204	   154	        "verificationMethod": [multikey(&vm_id, did, multibase)],
205	   155	        "authentication": [vm_id],
206	   156	        "assertionMethod": [vm_id],
207	   157	        "capabilityInvocation": [vm_id],
208	   158	        "capabilityDelegation": [vm_id],
209	   159	    }))
210	   160	}
