212	   162	fn peer_2_document(did: &str, elements: &str) -> Result<Document, ResolveError> {
213	   163	    let invalid = || ResolveError::InvalidDid(did.to_string());
214	   164	    let mut methods = Vec::new();
215	   165	    let mut relationships: Map<String, Value> = Map::new();
216	   166	    let mut services = Vec::new();
217	   167	
218	   168	    for element in elements.split('.') {
219	   169	        let mut chars = element.chars();
220	   170	        let purpose = chars.next().ok_or_else(invalid)?;
221	   171	        let body = chars.as_str();
222	   172	        let relationship = match purpose {
223	   173	            'A' => "assertionMethod",
224	   174	            'V' => "authentication",
225	   175	            'E' => "keyAgreement",
226	   176	            'I' => "capabilityInvocation",
227	   177	            'D' => "capabilityDelegation",
228	   178	            'S' => {
229	   179	                let raw = URL_SAFE_NO_PAD.decode(body.trim_end_matches('=')).map_err(|_| invalid())?;
230	   180	                let abbreviated: Value = serde_json::from_slice(&raw).map_err(|_| invalid())?;
231	   181	                let id = match services.len() {
232	   182	                    0 => format!("{did}#service"),
233	   183	                    n => format!("{did}#service-{n}"),
234	   184	                };
235	   185	                let mut service = expand_service(&abbreviated);
236	   186	                service["id"] = json!(id);
237	   187	                services.push(service);
238	   188	                continue;
239	   189	            }
240	   190	            _ => return Err(invalid()),
241	   191	        };
242	   192	        if purpose != 'E' {
243	   193	            ed25519_multikey(did, body)?;
244	   194	        }
245	   195	        let vm_id = format!("{did}#key-{}", methods.len() + 1);
246	   196	        methods.push(multikey(&vm_id, did, body));
247	   197	        relationships.entry(relationship).or_insert_with(|| json!([])).as_array_mut().unwrap().push(json!(vm_id));
248	   198	    }
249	   199	
250	   200	    let mut document = json!({
251	   201	        "@context": ["https://www.w3.org/ns/did/v1", "https://w3id.org/security/multikey/v1"],
252	   202	        "id": did,
253	   203	        "verificationMethod": methods,
254	   204	        "service": services,
255	   205	    });
256	   206	    for (relationship, ids) in relationships {
257	   207	        document[relationship] = ids;
258	   208	    }
259	   209	    to_document(did, document)
260	   210	}
261	   211	
262	   212	/// Expands the abbreviated keys peer:2 uses for services (`t`, `s`, `r`, `a`, `dm`).
263	   213	fn expand_service(value: &Value) -> Value {
264	   214	    match value {
265	   215	        Value::Object(map) => Value::Object(
266	   216	            map.iter()
267	   217	                .map(|(k, v)| {
268	   218	                    let key = match k.as_str() {
269	   219	                        "t" => "type",
270	   220	                        "s" => "serviceEndpoint",
271	   221	                        "r" => "routingKeys",
272	   222	                        "a" => "accept",
273	   223	                        other => other,
274	   224	                    };
275	   225	                    (key.to_string(), expand_service(v))
276	   226	                })
277	   227	                .collect(),
278	   228	        ),
279	   229	        Value::String(s) if s == "dm" => json!("DIDCommMessaging"),
280	   230	        Value::Array(items) => Value::Array(items.iter().map(expand_service).collect()),
281	   231	        other => other.clone(),
282	   232	    }
283	   233	}
284	   234	
285	   235	fn to_document(did: &str, value: Value) -> Result<Document, ResolveError> {
286	   236	    serde_json::from_value(value)
287	   237	        .map_err(|e| ResolveError::InvalidDocument { did: did.to_string(), reason: e.to_string() })
288	   238	}
