331	    42	    /// The mirror at `$DID_MIRROR_ROOT`, or the checked-in copy of the bucket.
332	    43	    pub fn from_env() -> Self {
333	    44	        match std::env::var_os("DID_MIRROR_ROOT") {
334	    45	            Some(root) => MirrorTransport::new(root),
335	    46	            None => MirrorTransport::new(Path::new(env!("CARGO_MANIFEST_DIR")).join("../reference/infra/hosted-dids")),
336	    47	        }
