339	    50	    fn path_for(&self, url: &str) -> Result<PathBuf, TransportError> {
340	    51	        let invalid = || TransportError::InvalidUrl(url.to_string());
341	    52	        let parsed = Url::parse(url).map_err(|_| invalid())?;
342	    53	        if parsed.scheme() != "https" || url.contains("/../") {
343	    54	            return Err(invalid());
344	    55	        }
345	    56	        let host = parsed.host_str().ok_or_else(invalid)?;
346	    57	        let authority = match parsed.port() {
347	    58	            Some(port) => format!("{host}:{port}"),
348	    59	            None => host.to_string(),
349	    60	        };
350	    61	        let mut path = self.root.join(authority);
351	    62	        for segment in parsed.path_segments().into_iter().flatten() {
352	    63	            let segment = Path::new(segment);
353	    64	            if segment.components().any(|c| !matches!(c, Component::Normal(_))) {
354	    65	                return Err(invalid());
355	    66	            }
356	    67	            path.push(segment);
357	    68	        }
358	    69	        Ok(path)
359	    70	    }
360	    71	}
