606	   216	fn listed_key(signer: &Document, relationship: &[VerificationRelationship], method: &str) -> Result<VerifyingKey, VerifyError> {
607	   217	    let unknown = || VerifyError::UnknownKey(method.to_string());
608	   218	    let absolute = |reference: &str| match reference.strip_prefix('#') {
609	   219	        Some(fragment) => format!("{}#{fragment}", signer.id),
610	   220	        None => reference.to_string(),
611	   221	    };
612	   222	    let listed = relationship.iter().find_map(|entry| match entry {
613	   223	        VerificationRelationship::Reference(reference) if absolute(reference) == method => {
614	   224	            signer.verification_method.iter().find(|vm| absolute(vm.id.as_str()) == method).cloned()
