     1	//! Fetching hosted DID documents.
     2	//!
     3	//! Issuer `did.json` documents are published to the document bucket behind
     4	//! the issuers' domains (see `reference/infra/hosted-dids/`). The service
     5	//! reads them through a [`DocumentTransport`], so the same resolver runs
     6	//! against the bucket mirror in development and against fixtures in tests.
     7	
     8	use std::collections::HashMap;
     9	use std::path::{Component, Path, PathBuf};
    10	
    11	use thiserror::Error;
    12	use url::Url;
    13	
    14	#[derive(Debug, Error, PartialEq, Eq)]
    15	pub enum TransportError {
    16	    #[error("invalid document URL {0}")]
    17	    InvalidUrl(String),
    18	    #[error("no document at {0}")]
    19	    NotFound(String),
    20	    #[error("reading {url}: {reason}")]
    21	    Io { url: String, reason: String },
    22	}
    23	
    24	/// Something that can GET a document by its HTTPS URL.
    25	pub trait DocumentTransport: Send + Sync {
    26	    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError>;
    27	}
    28	
    29	/// Serves `https://<authority>/<path>` from `<root>/<authority>/<path>`: a
    30	/// local mirror of the document bucket, laid out the way the bucket keys
    31	/// its objects.
    32	#[derive(Debug, Clone)]
    33	pub struct MirrorTransport {
    34	    root: PathBuf,
    35	}
    36	
    37	impl MirrorTransport {
    38	    pub fn new(root: impl AsRef<Path>) -> Self {
    39	        MirrorTransport { root: root.as_ref().to_path_buf() }
    40	    }
    41	
    42	    /// The mirror at `$DID_MIRROR_ROOT`, or the checked-in copy of the bucket.
    43	    pub fn from_env() -> Self {
    44	        match std::env::var_os("DID_MIRROR_ROOT") {
    45	            Some(root) => MirrorTransport::new(root),
    46	            None => MirrorTransport::new(Path::new(env!("CARGO_MANIFEST_DIR")).join("../reference/infra/hosted-dids")),
    47	        }
    48	    }
    49	
    50	    fn path_for(&self, url: &str) -> Result<PathBuf, TransportError> {
    51	        let invalid = || TransportError::InvalidUrl(url.to_string());
    52	        let parsed = Url::parse(url).map_err(|_| invalid())?;
    53	        if parsed.scheme() != "https" || url.contains("/../") {
    54	            return Err(invalid());
    55	        }
    56	        let host = parsed.host_str().ok_or_else(invalid)?;
    57	        let authority = match parsed.port() {
    58	            Some(port) => format!("{host}:{port}"),
    59	            None => host.to_string(),
    60	        };
    61	        let mut path = self.root.join(authority);
    62	        for segment in parsed.path_segments().into_iter().flatten() {
    63	            let segment = Path::new(segment);
    64	            if segment.components().any(|c| !matches!(c, Component::Normal(_))) {
    65	                return Err(invalid());
    66	            }
    67	            path.push(segment);
    68	        }
    69	        Ok(path)
    70	    }
    71	}
    72	
    73	impl DocumentTransport for MirrorTransport {
    74	    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError> {
    75	        let path = self.path_for(url)?;
    76	        std::fs::read(&path).map_err(|e| match e.kind() {
    77	            std::io::ErrorKind::NotFound => TransportError::NotFound(url.to_string()),
    78	            _ => TransportError::Io { url: url.to_string(), reason: e.to_string() },
    79	        })
    80	    }
    81	}
    82	
    83	/// An in-memory set of documents keyed by URL.
    84	#[derive(Debug, Clone, Default)]
    85	pub struct StaticTransport {
    86	    documents: HashMap<String, Vec<u8>>,
    87	}
    88	
    89	impl StaticTransport {
    90	    pub fn with(mut self, url: &str, body: impl Into<Vec<u8>>) -> Self {
    91	        self.documents.insert(url.to_string(), body.into());
    92	        self
    93	    }
    94	}
    95	
    96	impl DocumentTransport for StaticTransport {
    97	    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError> {
    98	        self.documents.get(url).cloned().ok_or_else(|| TransportError::NotFound(url.to_string()))
    99	    }
