   196	    /// The DID document an issuer's credentials are checked against.
   197	    pub fn resolve_issuer(&self, did: &str) -> Result<Document, VerifyError> {
   198	        if let Some(issuer) = self.store.onboarded_issuer(did) {
   199	            return Ok(issuer.document);
   200	        }
   201	        Ok(self.resolver.resolve(did)?)
   202	    }
   203	}
   204	
   205	/// Checks `document`'s proof against a key `signer` lists under `relationship`.
   206	fn check_proof(document: &Value, signer: &Document, relationship: &[VerificationRelationship]) -> Result<(), VerifyError> {
   207	    let proof = document.get("proof").ok_or_else(|| malformed("proof"))?;
   208	    if proof.get("type").and_then(Value::as_str) == Some(ED25519_SIGNATURE_2020) {
   209	        let method = proof.get("verificationMethod").and_then(Value::as_str).ok_or_else(|| malformed("proof.verificationMethod"))?;
   210	        let key = listed_key(signer, relationship, method)?;
   211	        credential::verify_signature(document, &key).map_err(VerifyError::BadSignature)?;
   212	    }
   213	    Ok(())
   214	}
   215	
   216	fn listed_key(signer: &Document, relationship: &[VerificationRelationship], method: &str) -> Result<VerifyingKey, VerifyError> {
   217	    let unknown = || VerifyError::UnknownKey(method.to_string());
   218	    let absolute = |reference: &str| match reference.strip_prefix('#') {
   219	        Some(fragment) => format!("{}#{fragment}", signer.id),
   220	        None => reference.to_string(),
   221	    };
   222	    let listed = relationship.iter().find_map(|entry| match entry {
   223	        VerificationRelationship::Reference(reference) if absolute(reference) == method => {
   224	            signer.verification_method.iter().find(|vm| absolute(vm.id.as_str()) == method).cloned()
   225	        }
   226	        VerificationRelationship::VerificationMethod(vm) if absolute(vm.id.as_str()) == method => Some((**vm).clone()),
   227	        _ => None,
   228	    });
   229	    let vm = listed.ok_or_else(unknown)?;
   230	    match vm.decode_public_key() {
   231	        Ok((affinidi_encoding::ED25519_PUB, bytes)) => {
   232	            let bytes: [u8; 32] = bytes.try_into().map_err(|_| unknown())?;
   233	            VerifyingKey::from_bytes(&bytes).map_err(|_| unknown())
   234	        }
   235	        _ => Err(unknown()),
   236	    }
   237	}
   238	
   239	fn malformed(field: &str) -> VerifyError {
   240	    VerifyError::Malformed(format!("missing or invalid {field}"))
   241	}
   242	
   243	fn str_field<'a>(value: &'a Value, field: &str) -> Result<&'a str, VerifyError> {
   244	    value.get(field).and_then(Value::as_str).ok_or_else(|| malformed(field))
   245	}
   246	
   247	fn int_field(value: &Value, field: &str) -> Result<i64, VerifyError> {
   248	    value.get(field).and_then(Value::as_i64).ok_or_else(|| malformed(field))
   249	}
   250	
   251	fn unix_now() -> i64 {
   252	    std::time::SystemTime::now()
   253	        .duration_since(std::time::UNIX_EPOCH)
   254	        .map(|d| d.as_secs() as i64)
   255	        .unwrap_or_default()
   256	}
