378	    for disclosure in &issued.disclosures {
379	        assert!(digests.contains(&disclosure.digest().as_str()), "{} is committed", disclosure.name);
380	        assert!(disclosure.salt.len() >= 16);
381	    }
382	    let text = issued.credential.to_string();
383	    assert!(!text.contains("gold") && !text.contains("1990-04-12"), "claim values stay out of the VC");
384	}
385	
386	#[test]
387	fn every_issue_uses_fresh_salts() {
388	    let store = store();
389	    let holder = Holder::new(1);
390	    let a = harbour().issue(&store, &membership_request(&holder)).unwrap();
391	    let b = harbour().issue(&store, &membership_request(&holder)).unwrap();
392	    assert_ne!(a.disclosures[0].salt, b.disclosures[0].salt);
393	    assert_ne!(a.credential["id"], b.credential["id"]);
394	}
395	
396	#[test]
397	fn the_issuer_proof_verifies_with_the_issuer_key() {
398	    let store = store();
399	    let holder = Holder::new(1);
400	    let issuer = harbour();
401	    let issued = issuer.issue(&store, &membership_request(&holder)).unwrap();
402	    assert!(credential::verify_signature(&issued.credential, &issuer.verifying_key()).is_ok());
403	}
404	
405	#[test]
406	fn issuance_is_recorded_in_the_store() {
407	    let store = store();
408	    let holder = Holder::new(1);
409	    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
410	    let record = store.credential(issued.credential["id"].as_str().unwrap()).unwrap();
411	    assert_eq!(record.issuer, HARBOUR_DID);
412	    assert_eq!(record.subject, holder.did);
413	    assert_eq!(record.status_index as u64, issued.credential["credentialStatus"]["statusListIndex"].as_u64().unwrap());
414	}
