416	#[test]
417	fn holders_must_be_did_key() {
418	    let store = store();
419	    let mut request = membership_request(&Holder::new(1));
420	    request.holder = "did:web:someone.example".into();
421	    assert!(matches!(harbour().issue(&store, &request), Err(IssueError::InvalidHolder(_))));
