432	#[test]
433	fn onboarding_records_the_published_document() {
434	    let resolver = Resolver::new(Arc::new(transport()));
435	    let store = Store::new();
436	
437	    let record = onboard(&resolver, &store, HARBOUR_DID, "Harbour Club", "2026-06-01").unwrap();
438	    assert_eq!(record.document.id.as_str(), HARBOUR_DID);
439	    assert_eq!(store.onboarded_issuer(HARBOUR_DID), Some(record));
