442	#[test]
443	fn onboarding_fails_when_the_document_is_unavailable() {
444	    let resolver = Resolver::new(Arc::new(StaticTransport::default()));
445	    let store = Store::new();
446	    assert!(onboard(&resolver, &store, HARBOUR_DID, "Harbour Club", "2026-06-01").is_err());
447	    assert!(store.onboarded_issuer(HARBOUR_DID).is_none());
