449	mod common;
450	
451	use credentials_backend::credential::{self, canonicalize, Disclosure};
452	use ed25519_dalek::SigningKey;
453	use serde_json::json;
454	
455	#[test]
456	fn canonical_form_sorts_keys_and_drops_whitespace() {
457	    let value = json!({ "b": 2, "a": [1, "x", true, null, { "d": {}, "c": [] }] });
458	    assert_eq!(canonicalize(&value), r#"{"a":[1,"x",true,null,{"c":[],"d":{}}],"b":2}"#);
459	}
460	
461	#[test]
462	fn canonical_form_orders_keys_by_utf16_code_units() {
463	    // U+1F600 is a surrogate pair (0xD83D..) and sorts before U+FB01 in UTF-16,
464	    // although its UTF-8 encoding sorts after.
465	    let value = json!({ "\u{FB01}": 1, "\u{1F600}": 2, "a": 3 });
466	    assert_eq!(canonicalize(&value), "{\"a\":3,\"\u{1F600}\":2,\"\u{FB01}\":1}");
467	}
468	
469	#[test]
470	fn canonical_form_escapes_only_what_json_requires() {
471	    let value = json!({ "s": "quote\" slash\\ tab\t nl\n ctl\u{1} é /" });
472	    assert_eq!(canonicalize(&value), "{\"s\":\"quote\\\" slash\\\\ tab\\t nl\\n ctl\\u0001 é /\"}");
473	}
474	
475	#[test]
476	fn canonical_form_writes_integral_numbers_without_a_fraction() {
477	    assert_eq!(canonicalize(&json!([1.0, -0.0, 2.5, 1_780_272_000i64])), "[1,0,2.5,1780272000]");
478	}
479	
480	#[test]
481	fn disclosure_digest_is_sha256_of_the_canonical_triple() {
482	    let d = Disclosure { salt: "c2FsdA".into(), name: "member".into(), value: json!(true) };
483	    // sha256(`["c2FsdA","member",true]`), base64url without padding
484	    assert_eq!(d.digest(), "c-ZiuLoNN9HMsfOE2LQWHZNCZJLLnzaxRm_5gNAPlR8");
485	}
486	
487	#[test]
488	fn signed_documents_verify_and_tampering_is_detected() {
489	    let key = SigningKey::from_bytes(&[3; 32]);
490	    let mut doc = json!({ "hello": "world", "n": 1 });
491	    credential::sign(&mut doc, &key, "did:example:1#k", "assertionMethod", 1_700_000_000);
492	
493	    let proof = &doc["proof"];
494	    assert_eq!(proof["type"], credential::ED25519_SIGNATURE_2020);
495	    assert_eq!(proof["verificationMethod"], "did:example:1#k");
496	    assert_eq!(proof["proofPurpose"], "assertionMethod");
497	    assert!(proof["proofValue"].as_str().unwrap().starts_with('z'));
498	
499	    assert!(credential::verify_signature(&doc, &key.verifying_key()).is_ok());
500	    doc["n"] = json!(2);
501	    assert!(credential::verify_signature(&doc, &key.verifying_key()).is_err());
502	}
503	
504	#[test]
505	fn signing_input_excludes_the_proof() {
506	    let key = SigningKey::from_bytes(&[4; 32]);
507	    let mut doc = json!({ "a": 1 });
508	    let before = credential::signing_input(&doc);
509	    credential::sign(&mut doc, &key, "did:example:1#k", "assertionMethod", 0);
510	    assert_eq!(credential::signing_input(&doc), before);
511	    assert_eq!(before, br#"{"a":1}"#.to_vec());
512	}

