127	
128	/// In-memory wallet storage: held credentials by id, and the holder key.
129	class CredentialStore {
130	  final Map<String, HeldCredential> _credentials = {};
131	
132	  void save(HeldCredential credential) =>
133	      _credentials[credential.id] = credential;
134	
135	  HeldCredential? byId(String id) => _credentials[id];
136	
137	  List<HeldCredential> all() => List.unmodifiable(_credentials.values);
138	
139	  HolderKey? holderKey;
140	}
141	/// One salted claim the holder can reveal: its digest sits in the credential.
142	class Disclosure {
143	  const Disclosure({
144	    required this.salt,
145	    required this.name,
146	    required this.value,
147	  });
148	
149	  factory Disclosure.fromJson(Object? json) {
150	    if (json is Map<String, dynamic>) {
151	      return Disclosure(
152	        salt: json['salt'] as String,
153	        name: json['name'] as String,
154	        value: json['value'],
155	      );
156	    }
157	    if (json is List && json.length == 3) {
158	      return Disclosure(
159	        salt: json[0] as String,
160	        name: json[1] as String,
161	        value: json[2],
162	      );
163	    }
164	    throw FormatException('Unrecognised disclosure: $json');
165	  }
166	
167	  final String salt;
168	  final String name;
169	  final Object? value;
170	
171	  Map<String, dynamic> toJson() => {'salt': salt, 'name': name, 'value': value};
172	}
173	
174	/// A credential in the wallet: the issuer-signed document plus the
175	/// disclosures that go with it.
176	class HeldCredential {
177	  HeldCredential({required this.vc, required this.disclosures});
178	
179	  /// Parses the issuer's response: `{"credential": {...}, "disclosures": [...]}`.
180	  factory HeldCredential.fromIssuance(Map<String, dynamic> json) {
181	    final vc = json['credential'];
182	    if (vc is! Map<String, dynamic>) {
183	      throw const FormatException('Issuance response has no credential');
184	    }
185	    final disclosures = (json['disclosures'] as List? ?? const [])
186	        .map(Disclosure.fromJson)
187	        .toList();
188	    return HeldCredential(vc: vc, disclosures: disclosures);
189	  }
190	
191	  final Map<String, dynamic> vc;
192	  final List<Disclosure> disclosures;
193	
194	  String get id => vc['id'] as String;
195	
196	  String get issuer {
197	    final issuer = vc['issuer'];
198	    return issuer is Map ? issuer['id'] as String : issuer as String;
199	  }
200	
201	  String? get holderDid =>
202	      (vc['credentialSubject'] as Map<String, dynamic>?)?['id'] as String?;
203	
204	  /// The most specific type, e.g. `MembershipCredential`.
205	  String get type {
206	    final types = vc['type'];
207	    return types is List ? types.last as String : types as String;
208	  }
209	
210	  Map<String, dynamic> toJson() => {
211	    'credential': vc,
212	    'disclosures': disclosures.map((d) => d.toJson()).toList(),
213	  };
214	}
215	import 'dart:typed_data';
216	
217	import 'package:ssi/ssi.dart';
218	
219	/// The holder's signing key and the did:key derived from it.
220	class HolderKey {
221	  HolderKey._(this.keyPair) : did = DidKey.getDid(keyPair.publicKey);
222	
223	  /// A fresh random Ed25519 key.
224	  factory HolderKey.generate() {
225	    final (keyPair, _) = Ed25519KeyPair.generate();
226	    return HolderKey._(keyPair);
227	  }
228	
229	  /// A key restored from its 32-byte seed.
230	  factory HolderKey.fromSeed(Uint8List seed) =>
231	      HolderKey._(Ed25519KeyPair.fromSeed(seed));
232	
233	  final Ed25519KeyPair keyPair;
234	  final String did;
235	
236	  /// The verification method id inside the did:key document.
237	  String get keyId => '$did#${did.substring('did:key:'.length)}';
238	
239	  Future<Uint8List> sign(List<int> data) =>
240	      keyPair.sign(Uint8List.fromList(data));
241	
242	  Future<bool> verify(List<int> data, List<int> signature) =>
243	      keyPair.verify(Uint8List.fromList(data), Uint8List.fromList(signature));
244	}
