246	
247	/// Talks to the issuer service.
248	abstract interface class IssuerClient {
249	  /// Asks the issuer for a [credentialType] credential about [holderDid].
250	  Future<HeldCredential> issue({
251	    required String holderDid,
252	    required String credentialType,
253	  });
254	}
255	import 'package:dcql/dcql.dart';
256	
257	/// A verifier's request for a presentation, in the OpenID4VP shape:
258	/// who is asking (`client_id`), a `nonce`, and a DCQL query.
259	class PresentationRequest {
260	  const PresentationRequest({
261	    required this.clientId,
262	    required this.nonce,
263	    required this.dcqlQuery,
264	    this.responseUri,
265	  });
266	
267	  factory PresentationRequest.fromJson(Map<String, dynamic> json) {
268	    final clientId = json['client_id'];
269	    final nonce = json['nonce'];
270	    final query = json['dcql_query'];
271	    if (clientId is! String || clientId.isEmpty) {
272	      throw const FormatException('Presentation request has no client_id');
273	    }
274	    if (nonce is! String || nonce.isEmpty) {
275	      throw const FormatException('Presentation request has no nonce');
276	    }
277	    if (query is! Map<String, dynamic>) {
278	      throw const FormatException('Presentation request has no dcql_query');
279	    }
280	    final responseUri = json['response_uri'];
281	    return PresentationRequest(
282	      clientId: clientId,
283	      nonce: nonce,
284	      dcqlQuery: DcqlCredentialQuery.fromJson(query),
285	      responseUri: responseUri is String ? Uri.parse(responseUri) : null,
286	    );
287	  }
288	
289	  final String clientId;
290	  final String nonce;
291	  final DcqlCredentialQuery dcqlQuery;
292	  final Uri? responseUri;
293	
294	  /// The domain a presentation for this request is addressed to.
295	  String get domain => clientId;
296	
297	  Map<String, dynamic> toJson() => {
298	    'client_id': clientId,
299	    'nonce': nonce,
300	    'dcql_query': dcqlQuery.toJson(),
301	    if (responseUri != null) 'response_uri': responseUri.toString(),
302	  };
303	}
304	import 'credential_store.dart';
305	import 'held_credential.dart';
306	import 'holder_key.dart';
307	import 'issuer_client.dart';
308	import 'presentation_request.dart';
309	
310	class WalletException implements Exception {
311	  const WalletException(this.message);
312	  final String message;
313	  @override
314	  String toString() => 'WalletException: $message';
315	}
316	
317	/// The wallet's operations: holder key, credential requests, presentations.
318	class WalletService {
319	  WalletService({
320	    required this._issuer,
321	    CredentialStore? store,
322	    HolderKey Function()? newKey,
323	  }) : _store = store ?? CredentialStore(),
324	       _newKey = newKey ?? HolderKey.generate;
325	
326	  final IssuerClient _issuer;
327	  final CredentialStore _store;
328	  final HolderKey Function() _newKey;
329	
330	  /// The holder key, created on first use.
331	  HolderKey holderKey() => _store.holderKey ??= _newKey();
332	
333	  /// Requests a [credentialType] credential for this holder and keeps it.
334	  Future<HeldCredential> requestCredential(String credentialType) async {
335	    final did = holderKey().did;
336	    final credential = await _issuer.issue(
337	      holderDid: did,
338	      credentialType: credentialType,
339	    );
340	    if (credential.holderDid != did) {
341	      throw WalletException(
342	        'Credential ${credential.id} was issued to ${credential.holderDid}, not $did',
343	      );
344	    }
345	    _store.save(credential);
346	    return credential;
347	  }
348	
349	  List<HeldCredential> heldCredentials() => _store.all();
350	
351	  HeldCredential? credential(String id) => _store.byId(id);
352	
353	  /// Builds a presentation of the held credential [credentialId] in answer
354	  /// to [request], ready to send to the requester.
355	  Future<Map<String, dynamic>> createPresentation(
356	    String credentialId,
357	    PresentationRequest request,
358	  ) async {
359	    throw UnimplementedError('createPresentation');
360	  }
361	}

