174	/// A credential in the wallet: the issuer-signed document plus the
175	/// disclosures that go with it.
176	class HeldCredential {
177	  HeldCredential({required this.vc, required this.disclosures});
178	
179	  /// Parses the issuer's response: `{"credential": {...}, "disclosures": [...]}`.
180	  factory HeldCredential.fromIssuance(Map<String, dynamic> json) {
181	    final vc = json['credential'];
182	    if (vc is! Map<String, dynamic>) {
183	      throw const FormatException('Issuance response has no credential');
184	    }
185	    final disclosures = (json['disclosures'] as List? ?? const [])
186	        .map(Disclosure.fromJson)
187	        .toList();
188	    return HeldCredential(vc: vc, disclosures: disclosures);
189	  }
190	
191	  final Map<String, dynamic> vc;
192	  final List<Disclosure> disclosures;
193	
194	  String get id => vc['id'] as String;
195	
196	  String get issuer {
197	    final issuer = vc['issuer'];
198	    return issuer is Map ? issuer['id'] as String : issuer as String;
199	  }
200	
201	  String? get holderDid =>
202	      (vc['credentialSubject'] as Map<String, dynamic>?)?['id'] as String?;
203	
204	  /// The most specific type, e.g. `MembershipCredential`.
205	  String get type {
206	    final types = vc['type'];
207	    return types is List ? types.last as String : types as String;
208	  }
209	
210	  Map<String, dynamic> toJson() => {
211	    'credential': vc,
212	    'disclosures': disclosures.map((d) => d.toJson()).toList(),
213	  };
