233	  final Ed25519KeyPair keyPair;
234	  final String did;
235	
236	  /// The verification method id inside the did:key document.
237	  String get keyId => '$did#${did.substring('did:key:'.length)}';
238	
239	  Future<Uint8List> sign(List<int> data) =>
240	      keyPair.sign(Uint8List.fromList(data));
241	
242	  Future<bool> verify(List<int> data, List<int> signature) =>
243	      keyPair.verify(Uint8List.fromList(data), Uint8List.fromList(signature));
