317	/// The wallet's operations: holder key, credential requests, presentations.
318	class WalletService {
319	  WalletService({
320	    required this._issuer,
321	    CredentialStore? store,
322	    HolderKey Function()? newKey,
323	  }) : _store = store ?? CredentialStore(),
324	       _newKey = newKey ?? HolderKey.generate;
325	
326	  final IssuerClient _issuer;
327	  final CredentialStore _store;
328	  final HolderKey Function() _newKey;
329	
330	  /// The holder key, created on first use.
331	  HolderKey holderKey() => _store.holderKey ??= _newKey();
332	
333	  /// Requests a [credentialType] credential for this holder and keeps it.
334	  Future<HeldCredential> requestCredential(String credentialType) async {
335	    final did = holderKey().did;
336	    final credential = await _issuer.issue(
337	      holderDid: did,
338	      credentialType: credentialType,
339	    );
340	    if (credential.holderDid != did) {
341	      throw WalletException(
342	        'Credential ${credential.id} was issued to ${credential.holderDid}, not $did',
343	      );
344	    }
345	    _store.save(credential);
346	    return credential;
347	  }
348	
349	  List<HeldCredential> heldCredentials() => _store.all();
350	
351	  HeldCredential? credential(String id) => _store.byId(id);
