use credentials_backend::issuer::Issuer;
use credentials_backend::notifier::*;
use credentials_backend::resolver::*;
use credentials_backend::settings::*;
use credentials_backend::status::*;
use credentials_backend::store::Store;
use credentials_backend::transport::MirrorTransport;
use credentials_backend::webhook::*;
use serde_json::json;
use common::*;

#[test]
fn p1_path_url() {
    println!("P1 {}", did_web_url("did:web:guild.northfield.example:chapters:north").unwrap());
    let r = Resolver::new(Arc::new(MirrorTransport::from_env()));
    for d in ["did:web:members.harbourclub.example","did:web:issuer.cedarrowing.example","did:web:guild.northfield.example:chapters:north","did:web:badges.kestrel-league.example"] {
        println!("P1 resolve {d}: {:?}", r.resolve(d).map(|x| x.verification_method.iter().map(|v| (v.id.to_string(), v.property_set["publicKeyMultibase"].clone())).collect::<Vec<_>>()).map_err(|e| e.to_string()));
    }
}

#[test]
fn p2_non_ed25519_proof_type_skips_check() {
    let store = store();
    let holder = Holder::new(1);
    let mut issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    issued.credential["expires_at"] = json!(NOW + 3650 * DAY);
    issued.credential["proof"]["type"] = json!("DataIntegrityProof");
    issued.credential["proof"]["proofValue"] = json!("zgarbage");
    println!("P2 tampered+DataIntegrityProof: {:?}", verifier(store).verify_credential(&issued.credential).map(|v| v.expires_at));
}

#[test]
fn p3_unregistered_did_key_issuer_accepted() {
    let store = store();
    let holder = Holder::new(1);
    let k = ed25519_dalek::SigningKey::from_bytes(&[42; 32]);
    let did = did_key_for(&k.verifying_key());
    let frag = did.trim_start_matches("did:key:").to_string();
    let rogue = Issuer::new(&did, &format!("{did}#{frag}"), &[42; 32]);
    let issued = rogue.issue(&store, &membership_request(&holder)).unwrap();
    let vp = holder.present(&issued, &["member"], NONCE, DOMAIN);
    println!("P3 rogue did:key issuer: {:?}", verifier(store).verify_presentation(&submission("r", vp), NONCE, DOMAIN).map(|v| v.credential.issuer));
}

#[test]
fn p4_status_index_edges() {
    let mut l = StatusList::new(8);
    let idx: Vec<_> = std::iter::from_fn(|| l.allocate()).collect();
    println!("P4 indexes for cap 8: {idx:?}");
