    println!("P4 revoke idx 8 then is_set(8) = {}", l.is_set(8));
}

#[test]
fn p5_same_credential_two_request_ids() {
    let store = store();
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let vp = holder.present(&issued, &["member"], NONCE, DOMAIN);
    let v = verifier(store);
    println!("P5 first {:?}", v.verify_presentation(&submission("a", vp.clone()), NONCE, DOMAIN).is_ok());
    println!("P5 same vp new request_id {:?}", v.verify_presentation(&submission("b", vp), NONCE, DOMAIN).is_ok());
}

#[tokio::test(start_paused = true)]
async fn p6_hang_blocks_rest() {
    let settings = Arc::new(SettingsStore::new());
    let t = Arc::new(HermeticTransport::new());
    let sink = Arc::new(MemorySink::default());
    let n = Notifier::new(settings.clone(), t.clone(), sink.clone());
    let tenant = "did:web:members.harbourclub.example";
    settings.put(Setting::new(tenant, "webhook/a-hang", WEBHOOK_KIND, json!({"url":"https://hang.example/"})));
    t.route("https://hang.example/", Endpoint::Hang);
    settings.put(Setting::new(tenant, "webhook/b-ok", WEBHOOK_KIND, json!({"url":"https://ok.example/"})));
    t.route("https://ok.example/", Endpoint::ok());
    let start = tokio::time::Instant::now();
    n.notify(&StatusChange{credential_id:"c".into(),issuer:tenant.into(),status_list:"l".into(),status_index:1,revoked:true}).await;
    println!("P6 elapsed {:?} ok.example received {} events {:?}", start.elapsed(), t.received("https://ok.example/").len(), sink.events());
}

#[tokio::test(start_paused = true)]
async fn p7_many_subscribers() {
    let settings = Arc::new(SettingsStore::new());
    let t = Arc::new(HermeticTransport::new());
    let sink = Arc::new(MemorySink::default());
    let n = Notifier::new(settings.clone(), t.clone(), sink.clone());
    let tenant = "did:web:members.harbourclub.example";
    for i in 0..250 { settings.put(Setting::new(tenant, &format!("pref/{i:04}"), "preference", json!({}))); }
    for i in 0..80 { let u = format!("https://rp{i}.example/"); settings.put(Setting::new(tenant, &format!("webhook/{i:03}"), WEBHOOK_KIND, json!({"url":u}))); t.route(&u, Endpoint::ok()); }
    n.notify(&StatusChange{credential_id:"c".into(),issuer:tenant.into(),status_list:"l".into(),status_index:1,revoked:true}).await;
    println!("P7 delivered {} of 80, canary_healthy={}", sink.events().iter().filter(|e| e.subscription != "canary").count(), n.canary_healthy());
    let _ = Duration::ZERO; let _ = credential::random_token(1); let _ = Store::new();
}
